Парсинг объекта JSON
Итак, имея все компоненты для парсинга, пора собрать их вместе! Выше мы разобрали, как можно собрать аннотации, спарсить значения и спарсить массивы. Осталось разобрать сам объект JSON. Выглядеть это будет следующим образом:
// Получение релевантных полей из рефлексии
template <std::meta::info T> 
consteval auto GetRelFuncs()
{
 return std::define_static_array(std::views::filter(
 std::meta::members_of(T, std::meta::access_context::unchecked()),
 [](auto & v)
 { return std::meta::has_identifier(v) && std::meta::is_function(v); }));
}

// Верхний уровень парсера
template <std::meta::info T>
std::pair<char *, typename[:T:]> ParseJson
(
 char * curr, 
 char * end
)
{
 using T_ = typename[:T:];
 // Получение аннотаций структуры
 constexpr StructAnnots strAnnots = StructAnnots::MkStrAnnots<T_>();

 // Делегирование непостоянного порядка в отдельную функцию
 if constexpr (strAnnots.m_random_order)
 return ParseJsonRandomOrder<T>(curr, end);

 T_ out{};
 assert(*curr == '{');

 // Получение нужных полей
 constexpr auto flds = GetRelFields<T_>();

 // Получение позиционного порядка полей
 // (Функция будет рассмотрена ниже)
 constexpr auto flds_ord = GetOrderedField<T_>();
 constexpr auto sz = flds.size();

 template for (constexpr auto idx : std::views::indices(sz))
 {
 curr++;
 // Получение следующего по позиции поля
 constexpr auto curr_fld = flds[flds_ord[idx]];

 // Получение аннотаций к полю
 constexpr FieldAnnots curr_ann = FieldAnnots::MkFieldAnnots<curr_fld>();

 constexpr char delim = idx + 1 == sz ? '}' : ',';

 // Делегация парсинга дальше
 std::tie(curr, out.[:curr_fld:]) = 
 ParseObj<curr_fld, curr_ann.m_sz, curr_ann.m_min_sz,
 strAnnots.m_compressed, delim>
 (curr, end);
 }
 if constexpr (!strAnnots.m_compressed)
 SKP_SPC();
 assert(*curr == '}');
 curr++;
 if constexpr (!strAnnots.m_compressed)
 SKP_SPC();
 return {curr, out};
}
В коде выше мы берем нужные аннотации, вычисляем поля в целевой структуре и обозначаем цикл для парсинга каждого поля. Перед тем, как перейти к самому парсеру, немного поговорим об функции для сортировки порядка полей. Не буду ее выводить так как она вышла достаточно объемной и состоит из приемов, которые уже были видны ранее. В ней мы на этапе компиляции собираем всю информацию (есть ли позиция, применим ли алфавитный порядок и тому подобное) и на основе нее одну за другой расставляем по порядку. Немного рефлексии и здравого смысла решают эту проблему. Такие алгоритмы писать довольно приятно зная, что сложность и множество аспектов производительности попросту неважны так как операция не влияет на runtime программы.
Теперь рассмотрим сам парсер:
template <
 std::meta::info curr_fld, // информация о поле для парсинга
 int sz, // фиксированный размер в строке (если известен)
 int min_sz, // минимальный размер в строке (если известен)
 bool compressed, // присутствуют ли лишние пробелы, табуляции и т.п.?
 char Delim // разделитель после значения (запятая или полускобка)
>
static std::pair<char *, typename[:std::meta::type_of(curr_fld):]>
ParseObj
(
 char * curr, 
 char * end
)
{
 constexpr auto t = std::meta::type_of(curr_fld);

 // Получение аннотаций
 constexpr FieldAnnots curr_ann = FieldAnnots::MkFieldAnnots<curr_fld>();

 // Получение индентификатора
 constexpr std::string_view ident = std::meta::identifier_of(curr_fld);

 typename[:t:] out;

 // выявление имени поля - или идентификатор или аннотация DisplayName
 std::string_view disp_name = std::string_view(curr_ann.m_disp_name.begin());
 std::string_view name = curr_ann.m_disp_name[0] == '\0' ? ident : disp_name;

 if constexpr (!compressed)
 SKP_SPC();

 // Проверка на отсутствие поля
 if constexpr (curr_ann.m_may_absent)
 {
 static_assert(IsOption<std::meta::type_of(curr_fld)>());
 if (end - curr < name.size() + 2)
 return {curr, out};
 char * old = curr;

 // Попытка пропуска поля при условии соответствия названия
 SKP_IF_SV_G(name);
 // field is absent?
 if (curr == old)
 {
 out = std::nullopt;
 --curr;
 return {curr, out};
 }
 }
 // пропуск поля с верификацией в режиме отладки
 else
 {
 if constexpr (!compressed)
 SKP_SPC();

 assert(*curr == '"');
 SKP_STR_SV(name);
 }
 <...>

 // парсинг самого значения (разобрано выше)
 auto [after, v] = ParseVal<t, sz, min_sz, curr_ann.m_static_sz, compressed,
 Delim, curr_ann.m_ignore>(curr, end);

 return {after, v};
}
Как видно, мы точно так же получаем релевантные характеристики конкретного поля и пропускаем его, прибавляя длину поля к нашему указателю. Далее, когда указатель попадает на начало значения, вызывается разобранная ранее функция парсинга значения поля.
